func test_pipe_syntax_TestPipeSyntax_test_extend(self *Case, a Args) Value {
	self.L(456).ValidateIdentity("FROM x |> EXTEND id IN (1, 2) AS is_1_2, id + 1 as a_id", "WITH __tmp1 AS (SELECT *, id IN (1, 2) AS is_1_2, id + 1 AS a_id FROM x) SELECT * FROM __tmp1")
	self.L(460).ValidateIdentity("FROM x |> SELECT x.x1, x.x2 |> EXTEND x1 + 1 as x1_1, x2 + 1 as x2_1 |> WHERE x1_1 > 0 AND x2_1 > 0", "WITH __tmp1 AS (SELECT x.x1, x.x2 FROM x), __tmp2 AS (SELECT *, x1 + 1 AS x1_1, x2 + 1 AS x2_1 FROM __tmp1) SELECT * FROM __tmp2 WHERE x1_1 > 0 AND x2_1 > 0")
	self.L(464).ValidateIdentity("FROM (SELECT 'foo1' AS item1, 2 AS item2 UNION ALL SELECT 'foo2' AS item1, 5 AS item2) |> EXTEND SUM(item2) OVER() AS item2_sum", "SELECT * FROM (WITH __tmp1 AS (SELECT *, SUM(item2) OVER () AS item2_sum FROM (SELECT 'foo1' AS item1, 2 AS item2 UNION ALL SELECT 'foo2' AS item1, 5 AS item2)) SELECT * FROM __tmp1)")
	return nil
}

func test_pipe_syntax_TestPipeSyntax_test_tablesample(self *Case, a Args) Value {
	self.L(470).ValidateIdentity("FROM x |> TABLESAMPLE SYSTEM (1 PERCENT)", "SELECT * FROM x TABLESAMPLE SYSTEM (1 PERCENT)")
	self.L(474).ValidateIdentity("FROM x |> SELECT x.x1 |> TABLESAMPLE SYSTEM (1 PERCENT)", "WITH __tmp1 AS (SELECT x.x1 FROM x TABLESAMPLE SYSTEM (1 PERCENT)) SELECT * FROM __tmp1")
	self.L(478).ValidateIdentity("FROM x |> TABLESAMPLE SYSTEM (1 PERCENT) |> WHERE x.x1 > 0 |> SELECT x1, x2", "WITH __tmp1 AS (SELECT x1, x2 FROM x WHERE x.x1 > 0 TABLESAMPLE SYSTEM (1 PERCENT)) SELECT * FROM __tmp1")
	return nil
}
